(6071911, 893500, 23484, '<td valign="top">I love the grainy B&amp;W.</td>', 'I love the grainy B&W.', '2010-06-28 08:25:50.000000', NULL, 1),
(6071918, 893709, 81362, '<td valign="top">I''m enjoying the reflection and the dusty imperfections of the blue lining that convey a sense of time passing. Light (window?) adds dimension. Might have been stronger if the background in upper right could have been uniform.</td>', 'I''m enjoying the reflection and the dusty imperfections of the blue lining that convey a sense of time passing. Light (window?) adds dimension. Might have been stronger if the background in upper right could have been uniform.', '2010-06-28 08:51:05.000000', NULL, 1),
