(6071992, 893888, 15711, '<td valign="top">Nice.  I like the sense of melancholy.  I hope you''re not that sad. :) 7</td>', 'Nice.  I like the sense of melancholy.  I hope you''re not that sad. :) 7', '2010-06-28 11:24:20.000000', NULL, 1),
(6071994, 893349, 15711, '<td valign="top">Interesting.  I like the abstract feel of it.  Almost looks like I''m seeing the skeleton of an ankle and foot. :)</td>', 'Interesting.  I like the abstract feel of it.  Almost looks like I''m seeing the skeleton of an ankle and foot. :)', '2010-06-28 11:24:55.000000', NULL, 1),
