(6073204, 893777, 10785, '<td valign="top">Good perspective adds interest to the composition. Nice textured grass and good contrast giving richness to the color. One improvement idea might be to shoot from above in order to limit the background shrubbery and fence.</td>', 'Good perspective adds interest to the composition. Nice textured grass and good contrast giving richness to the color. One improvement idea might be to shoot from above in order to limit the background shrubbery and fence.', '2010-06-29 14:37:46.000000', NULL, 1),
(6073206, 893901, 10785, '<td valign="top">Your processing has moved this image from the realm of light and shadow into the twilight zone.</td>', 'Your processing has moved this image from the realm of light and shadow into the twilight zone.', '2010-06-29 14:38:43.000000', NULL, 1),
(6073486, 893247, 77551, '<td valign="top">Love it! 10</td>', 'Love it! 10', '2010-06-29 22:50:59.000000', NULL, 1),
(6073504, 893676, 40391, '<td valign="top">Fantastic shot!  This was my pick for the challenge and my only 10 vote. The lighting, composition and PP are great.  This really nails the challenge criteria IMHO.  Well done and I expect to see this on the front page.</td>', 'Fantastic shot!  This was my pick for the challenge and my only 10 vote. The lighting, composition and PP are great.  This really nails the challenge criteria IMHO.  Well done and I expect to see this on the front page.', '2010-06-29 23:17:40.000000', NULL, 1),
(6073511, 893886, 37845, '<td valign="top">My clear favourite in this challenge. I like how this wasnt just a random assortment of stuff, but rather an indirect way of looking at the psyche of the person.</td>', 'My clear favourite in this challenge. I like how this wasnt just a random assortment of stuff, but rather an indirect way of looking at the psyche of the person.', '2010-06-29 23:22:19.000000', NULL, 1),
